// This file is generated by AI.

// 生成快照的**前置**对话框: 说明打包规则 + 指定输出路径, 确认后才开始打包。
//
// 为什么要先问一句, 而不是直接弹系统保存框: 快照是"精简打包" —— 只把被语句与配置
// 引用到的资源放进压缩包, 未引用的资源不会进去。这件事必须在开始之前讲清楚, 尤其是
// 变量插值拼出来的资源名拿不到 (见下方提示), 否则用户会以为包是坏的。
//
// 输出路径可编辑: 系统保存框只能选位置, 想直接把路径粘进来 (或改个文件名) 时它帮不上忙。

import { Button, Input } from '@fluentui/react-components';
import { FolderRegular } from '@fluentui/react-icons';
import { save as saveDialog } from '@tauri-apps/plugin-dialog';
import { useState } from 'react';

import { AppDialog } from './AppDialog';

interface Props {
  /** 默认输出路径 (项目目录/<项目名>.zip) */
  defaultPath: string;
  onClose: () => void;
  /** 用户确认后的输出路径 */
  onStart: (destination: string) => void;
}

/** 补上 .zip 扩展名 (大小写不敏感); 已有扩展名时原样返回 */
function withZipExtension(path: string): string {
  return /\.zip$/i.test(path) ? path : `${path}.zip`;
}

export function SnapshotSetupDialog({ defaultPath, onClose, onStart }: Props) {
  const [path, setPath] = useState(defaultPath);

  const pick = async () => {
    const picked = await saveDialog({
      defaultPath: path.trim() || defaultPath,
      filters: [{ name: 'Zip 压缩包', extensions: ['zip'] }],
    });
    if (typeof picked === 'string') setPath(picked);
  };

  const destination = path.trim();

  return (
    <AppDialog
      title="生成快照"
      description="把当前项目打包成精简压缩包，用于分发或归档。"
      size="form"
      height="auto"
      onClose={onClose}
      footer={
        <>
          <Button appearance="secondary" onClick={onClose}>
            取消
          </Button>
          <Button
            appearance="primary"
            disabled={destination === ''}
            onClick={() => onStart(withZipExtension(destination))}
          >
            开始打包
          </Button>
        </>
      }
    >
      <p className="snapshot-intro">从初始场景 start.txt 和配置出发，收集引用到的资源，其余文件原样保留。</p>

      <p className="snapshot-note">
        <strong>变量插值拼出的资源名不会进包</strong>
        {
          '：bg:{bgName}、callScene:{chapter} 这类名字打包器只看到字面量，资源找不到也不会被打包。请改用字面量，或打包后手动补进压缩包。'
        }
      </p>

      <div className="settings-field">
        <span className="settings-label">输出路径</span>
        <div className="input-row">
          <Input value={path} aria-label="输出路径" title={path} onChange={(_, data) => setPath(data.value)} />
          <Button
            appearance="secondary"
            icon={<FolderRegular />}
            aria-label="选择输出路径"
            title="选择输出路径"
            onClick={() => void pick()}
          />
        </div>
        <span className="prompt-hint">所在目录需要已存在；同名文件会被覆盖。</span>
      </div>
    </AppDialog>
  );
}
